#!/usr/bin/env python3
import os, base64

DIRS = ['backend', 'backend/api', 'backend/api/routers', 'backend/db', 'backend/prompts', 'backend/schemas', 'backend/services', 'frontend', 'frontend/streamlit', 'frontend/streamlit/pages', 'frontend/streamlit/pages/create_new_issuance', 'frontend/streamlit/pages/manage_activities', 'frontend/streamlit/pages/manage_issuances']

FILES = {
    'README.md': '',
    'backend/README.md': '',
    'backend/__init__.py': 'IiIiQmFja2VuZCBwYWNrYWdlIHJvb3QuIiIiCg==',
    'backend/api/__init__.py': 'IiIiQVBJIHBhY2thZ2UuIiIiCg==',
    'backend/api/dependencies.py': '',
    'backend/api/routers/__init__.py': 'IiIiUm91dGVycyBwYWNrYWdlLiIiIgo=',
    'backend/api/routers/activities.py': '',
    'backend/api/routers/extraction.py': '',
    'backend/api/routers/issuance_activity_mapping.py': '',
    'backend/api/routers/issuances.py': '',
    'backend/db/init_db.py': '',
    'backend/db/session.py': '',
    'backend/main.py': '',
    'backend/prompts/issuance_extraction_prompt.md': '',
    'backend/schemas/__init__.py': '',
    'backend/schemas/activity.py': '',
    'backend/schemas/field_config.py': '',
    'backend/schemas/issuance.py': '',
    'backend/schemas/issuance_components.py': '',
    'backend/services/__init__.py': 'IiIiU2VydmljZXMgcGFja2FnZS4iIiIK',
    'backend/services/extract_pdf.py': '',
    'backend/services/instantiate_llm.py': '',
    'frontend/streamlit/README.md': '',
    'frontend/streamlit/__init__.py': 'IA==',
    'frontend/streamlit/home.py': '',
    'frontend/streamlit/pages/create_new_issuance/create_new_issuance_page.py': '',
    'frontend/streamlit/pages/create_new_issuance/create_new_issuances_components.py': '',
    'frontend/streamlit/pages/manage_activities/manage_activities_components.py': '',
    'frontend/streamlit/pages/manage_activities/manage_activities_page.py': '',
    'frontend/streamlit/pages/manage_issuances/manage_issuances_page.py': '',
    'requirements.txt': '',
}

def main():
    # Create directories
    for d in DIRS:
        os.makedirs(d, exist_ok=True)

    # Write files
    for path, b64 in FILES.items():
        data = base64.b64decode(b64)
        full_path = os.path.abspath(path)
        dirpath = os.path.dirname(full_path)
        os.makedirs(dirpath, exist_ok=True)
        with open(full_path, "wb") as f:
            f.write(data)

if __name__ == "__main__":
    main()
